/// Tracks definition context for a logical line and owns the pycodestyle
/// logical-line whitespace checks that consult that context.
#[derive(Debug, Clone, Default)]
pub(crate) struct DefinitionState {
    kind: DefinitionKind,
    named_param_scan: NamedParamScan,
    operator_scan: OperatorScan,
    enclosure_scan: EnclosureScan,
    spacing_scan: SpacingScan,
}

#[derive(Debug, Clone, Copy, Default)]
enum DefinitionKind {
    InClass(TypeParamsState),
    InFunction(TypeParamsState),
    InTypeAlias(TypeParamsState),
    #[default]
    NotInDefinition,
}

#[derive(Debug, Clone, Default)]
struct NamedParamScan {
    parens: u32,
    fstrings: u32,
    annotated_func_arg: bool,
    prev_end: TextSize,
}

#[derive(Debug, Clone, Default)]
struct OperatorScan {
    parens: u32,
    fstrings: u32,
}

#[derive(Debug, Clone, Default)]
struct EnclosureScan {
    stack: Vec<TokenKind>,
    fstrings: u32,
    prev_kind: Option<TokenKind>,
}

#[derive(Debug, Clone, Default)]
struct SpacingScan {
    after_operator: bool,
    after_keyword: bool,
    cursor: TextSize,
    prev_kind: Option<TokenKind>,
    prev_prev_kind: Option<TokenKind>,
}

impl DefinitionState {
    fn from_tokens<'a>(tokens: impl IntoIterator<Item = &'a LogicalLineToken>) -> Self {
        let mut state = Self::default();
        state.capture_definition_from_tokens(tokens);
        state
    }

    fn capture_definition_from_tokens<'a>(
        &mut self,
        tokens: impl IntoIterator<Item = &'a LogicalLineToken>,
    ) {
        self.kind = DefinitionKind::NotInDefinition;
        let mut token_kinds = tokens.into_iter().map(LogicalLineToken::kind);
        while let Some(token_kind) = token_kinds.next() {
            if self.consume_leading_definition_token(token_kind, &mut token_kinds) {
                return;
            }
        }
        self.set_kind_none();
    }

    fn consume_leading_definition_token<I>(
        &mut self,
        token_kind: TokenKind,
        token_kinds: &mut I,
    ) -> bool
    where
        I: Iterator<Item = TokenKind>,
    {
        match token_kind {
            TokenKind::Indent | TokenKind::Dedent => false,
            TokenKind::Class => {
                self.set_kind_class();
                true
            }
            TokenKind::Def => {
                self.set_kind_function();
                true
            }
            TokenKind::Async if matches!(token_kinds.next(), Some(TokenKind::Def)) => {
                self.set_kind_function();
                true
            }
            TokenKind::Type => {
                self.set_kind_type_alias();
                true
            }
            _ => {
                self.set_kind_none();
                true
            }
        }
    }

    fn set_kind_class(&mut self) {
        self.kind = DefinitionKind::InClass(TypeParamsState::default());
    }

    fn set_kind_function(&mut self) {
        self.kind = DefinitionKind::InFunction(TypeParamsState::default());
    }

    fn set_kind_type_alias(&mut self) {
        self.kind = DefinitionKind::InTypeAlias(TypeParamsState::default());
    }

    fn set_kind_none(&mut self) {
        self.kind = DefinitionKind::NotInDefinition;
    }

    const fn in_function_definition(&self) -> bool {
        matches!(self.kind, DefinitionKind::InFunction(_))
    }

    fn in_type_params(&self) -> bool {
        matches!(
            self.kind,
            DefinitionKind::InClass(TypeParamsState::InTypeParams { .. })
                | DefinitionKind::InFunction(TypeParamsState::InTypeParams { .. })
                | DefinitionKind::InTypeAlias(TypeParamsState::InTypeParams { .. })
        )
    }

    fn visit_token_kind(&mut self, token_kind: TokenKind) {
        let type_params_state_mut = match &mut self.kind {
            DefinitionKind::InClass(type_params_state)
            | DefinitionKind::InFunction(type_params_state)
            | DefinitionKind::InTypeAlias(type_params_state) => type_params_state,
            DefinitionKind::NotInDefinition => return,
        };
        match token_kind {
            TokenKind::Lpar if type_params_state_mut.before_type_params() => {
                *type_params_state_mut = TypeParamsState::TypeParamsEnded;
            }
            TokenKind::Lsqb => match type_params_state_mut {
                TypeParamsState::TypeParamsEnded => {}
                TypeParamsState::BeforeTypeParams => {
                    *type_params_state_mut = TypeParamsState::InTypeParams {
                        inner_square_brackets: 0,
                    };
                }
                TypeParamsState::InTypeParams {
                    inner_square_brackets,
                } => *inner_square_brackets += 1,
            },
            TokenKind::Rsqb => {
                if let TypeParamsState::InTypeParams {
                    inner_square_brackets,
                } = type_params_state_mut
                {
                    if *inner_square_brackets == 0 {
                        *type_params_state_mut = TypeParamsState::TypeParamsEnded;
                    } else {
                        *inner_square_brackets -= 1;
                    }
                }
            }
            _ => {}
        }
    }

