pub(crate) fn check_named_parameter_equals(
    &mut self,
    line: &LogicalLine,
    context: &mut LogicalLinesContext,
) {
    self.named_param_scan = NamedParamScan::default();
    let mut iter = line.tokens().iter().peekable();
    while let Some(token) = iter.next() {
        let kind = token.kind();
        self.visit_token_kind(kind);
        match kind {
            TokenKind::NonLogicalNewline => continue,
            TokenKind::FStringStart => self.note_named_param_fstring_start(),
            TokenKind::FStringEnd => self.note_named_param_fstring_end(),
            TokenKind::Lpar | TokenKind::Lsqb => self.note_named_param_open(),
            TokenKind::Rpar | TokenKind::Rsqb => self.note_named_param_close(),
            TokenKind::Colon if self.named_param_colon_annotates_argument() => {
                self.note_named_param_colon();
            }
            TokenKind::Comma if self.named_param_comma_resets_annotation() => {
                self.note_named_param_comma();
            }
            TokenKind::Equal if self.named_param_equal_is_active() => {
                if self.named_param_equal_needs_spaces() {
                    if self.named_param_missing_space_before(token) {
                        let mut diagnostic = Diagnostic::new(
                            MissingWhitespaceAroundParameterEquals,
                            token.range,
                        );
                        diagnostic.set_fix(Fix::safe_edit(Edit::insertion(
                            " ".to_string(),
                            token.start(),
                        )));
                        context.push_diagnostic(diagnostic);
                    }
                    while let Some(next) = iter.peek() {
                        if next.kind() == TokenKind::NonLogicalNewline {
                            iter.next();
                        } else {
                            if next.start() == token.end() {
                                let mut diagnostic = Diagnostic::new(
                                    MissingWhitespaceAroundParameterEquals,
                                    token.range,
                                );
                                diagnostic.set_fix(Fix::safe_edit(Edit::insertion(
                                    " ".to_string(),
                                    token.end(),
                                )));
                                context.push_diagnostic(diagnostic);
                            }
                            break;
                        }
                    }
                } else {
                    if token.start() != self.named_param_scan.prev_end {
                        let mut diagnostic = Diagnostic::new(
                            UnexpectedSpacesAroundKeywordParameterEquals,
                            TextRange::new(self.named_param_scan.prev_end, token.start()),
                        );
                        diagnostic.set_fix(Fix::safe_edit(Edit::deletion(
                            self.named_param_scan.prev_end,
                            token.start(),
                        )));
                        context.push_diagnostic(diagnostic);
                    }
                    while let Some(next) = iter.peek() {
                        if next.kind() == TokenKind::NonLogicalNewline {
                            iter.next();
                        } else {
                            if next.start() != token.end() {
                                let mut diagnostic = Diagnostic::new(
                                    UnexpectedSpacesAroundKeywordParameterEquals,
                                    TextRange::new(token.end(), next.start()),
                                );
                                diagnostic.set_fix(Fix::safe_edit(Edit::deletion(
                                    token.end(),
                                    next.start(),
                                )));
                                context.push_diagnostic(diagnostic);
                            }
                            break;
                        }
                    }
                }
            }
            _ => {}
        }
        self.remember_named_param_end(token);
    }
}

fn note_named_param_fstring_start(&mut self) {
    self.named_param_scan.fstrings = self.named_param_scan.fstrings.saturating_add(1);
}

fn note_named_param_fstring_end(&mut self) {
    self.named_param_scan.fstrings = self.named_param_scan.fstrings.saturating_sub(1);
}

fn note_named_param_open(&mut self) {
    self.named_param_scan.parens = self.named_param_scan.parens.saturating_add(1);
}

fn note_named_param_close(&mut self) {
    self.named_param_scan.parens = self.named_param_scan.parens.saturating_sub(1);
    if self.named_param_scan.parens == 0 {
        self.named_param_scan.annotated_func_arg = false;
    }
}

fn named_param_colon_annotates_argument(&self) -> bool {
    self.named_param_scan.parens == 1 && self.in_function_definition()
}

fn note_named_param_colon(&mut self) {
    if self.named_param_scan.parens == 1 {
        self.named_param_scan.annotated_func_arg = true;
    }
}

fn named_param_comma_resets_annotation(&self) -> bool {
    self.named_param_scan.parens == 1
}

fn note_named_param_comma(&mut self) {
    if self.named_param_scan.parens == 1 {
        self.named_param_scan.annotated_func_arg = false;
    }
}

fn named_param_equal_is_active(&self) -> bool {
    self.in_type_params()
        || (self.named_param_scan.parens > 0 && self.named_param_scan.fstrings == 0)
}

fn named_param_equal_needs_spaces(&self) -> bool {
    self.in_type_params()
        || (self.named_param_scan.annotated_func_arg && self.named_param_scan.parens == 1)
}

fn named_param_missing_space_before(&self, token: &LogicalLineToken) -> bool {
    token.start() == self.named_param_scan.prev_end
        && self.named_param_scan.prev_end != TextSize::new(0)
}

fn remember_named_param_end(&mut self, token: &LogicalLineToken) {
    self.named_param_scan.prev_end = token.end();
}

